}

{
  "type": "object",
  "properties": {
    "incidentId": {
      "type": "string"
    },
    "tool": {
      "type": "string",
      "enum": [
        "rollback_deployment",
        "restart_service",
        "scale_service",
        "disable_feature_flag"
      ]
    },
    "args": {
      "type": "object",
      "description": "Exact arguments the action will run with."
    },
    "reason": {
      "type": "string",
      "description": "Why this action, in two or three sentences."
    },
    "evidenceRefs": {
      "type": "array",
      "description": "Ids of the logs, traces, metric windows, and deployments supporting this proposal.",
      "items": {
        "type": "object",
        "properties": {
          "kind": {
            "type": "string",
            "enum": [
              "log",
              "trace",
              "metric_window",
              "deployment",
              "change"
            ]
          },
          "id": {
            "type": "string"
          },
          "label": {
            "type": "string"
          }
        }
      }
    },
    "expectedEffect": {
      "type": "string",
      "description": "What should change, and roughly how quickly."
    },
    "notCovered": {
      "type": "string",
      "description": "What this action does NOT address."
    },
    "risk": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high"
      ]
    }
  },
  "required": [
    "incidentId",
    "tool",
    "args",
    "reason",
    "evidenceRefs",
    "expectedEffect",
    "notCovered",
    "risk"
  ]
}

{
  "type": "object",
  "properties": {
    "note": {
      "type": "string",
      "description": "Plain text. State findings and uncertainty explicitly."
    }
  },
  "required": [
    "note"
  ]
}

{
  "type": "object",
  "properties": {
    "title": {
      "type": "string",
      "description": "Short incident title."
    },
    "severity": {
      "type": "string",
      "anyOf": [
        {
          "type": "string",
          "const": "",
          "title": "severity"
        },
        {
          "type": "string",
          "const": "SEV-1",
          "title": "SEV-1"
        },
        {
          "type": "string",
          "const": "SEV-2",
          "title": "SEV-2"
        },
        {
          "type": "string",
          "const": "SEV-3",
          "title": "SEV-3"
        }
      ],
      "enum": [
        "",
        "SEV-1",
        "SEV-2",
        "SEV-3"
      ],
      "description": "SEV-1, SEV-2, or SEV-3."
    },
    "affectedServices": {
      "type": "array",
      "items": {
        "type": "string",
        "anyOf": [
          {
            "type": "string",
            "const": "frontend",
            "title": "frontend"
          },
          {
            "type": "string",
            "const": "checkout",
            "title": "checkout"
          },
          {
            "type": "string",
            "const": "payments",
            "title": "payments"
          },
          {
            "type": "string",
            "const": "auth",
            "title": "auth"
          },
          {
            "type": "string",
            "const": "database",
            "title": "database"
          },
          {
            "type": "string",
            "const": "queue",
            "title": "queue"
          },
          {
            "type": "string",
            "const": "notifications",
            "title": "notifications"
          }
        ],
        "enum": [
          "frontend",
          "checkout",
          "payments",
          "auth",
          "database",
          "queue",
          "notifications"
        ]
      },
      "uniqueItems": true,
      "description": "One or more affected services."
    },
    "description": {
      "type": "string",
      "description": "Optional free-text description, becomes the first note."
    }
  },
  "required": [
    "title",
    "severity",
    "affectedServices"
  ]
}
